<?php

namespace App\Notifications;

use Illuminate\Bus\Queueable;
use Illuminate\Notifications\Messages\MailMessage;
use Illuminate\Notifications\Notification;

/**
 * The signup OTP: six digits, fifteen minutes, no links.
 *
 * The code is generated by the user's own sendEmailVerificationNotification()
 * and exists in plain text ONLY here — the database carries a hash. A leaked
 * code is worth nothing: it expires in fifteen minutes and one verification
 * burns it.
 */
class VerifyEmailCode extends Notification
{
    use Queueable;

    public function __construct(public readonly string $code)
    {
    }

    public function via($notifiable): array
    {
        return ['mail'];
    }

    public function toMail($notifiable)
    {
        return (new MailMessage)
            ->subject('Your TraMatch verification code')
            ->greeting('Hi '.($notifiable->name ?: 'there').',')
            ->line('Enter this six-digit code to finish signing up:')
            ->line('**'.$this->code.'**')
            ->line('The code expires in 15 minutes. If you did not try to sign up, you can ignore this email.');
    }
}
